// Brand: a gambrel barn drawn as a letter A (the hayloft beam is its crossbar, the door its counter),
// and a slab "AGRARIAN" wordmark drawn as paths, so it renders the same everywhere.
// The art is generated by scripts/brand/build.py into logoArt.ts.
import { LOCKUP, MARK, MARK_MONO, TONES, WORD, WORD_WIDTH } from './logoArt';

/** auto follows the app theme; light/dark force a palette; mono is one colour (currentColor), for watermarks. */
export type LogoVariant = 'auto' | 'light' | 'dark' | 'mono';
type Face = keyof typeof MARK;
const FACES: Face[] = ['base', 'roofL', 'roofR', 'wallL', 'wallR', 'window'];

const fill = (v: LogoVariant, k: Face | 'ink') =>
  v === 'mono' ? 'currentColor' : v === 'auto' ? `var(--logo-${k}, ${TONES.light[k]})` : TONES[v][k];

function MarkArt({ variant }: { variant: LogoVariant }) {
  if (variant === 'mono') return <path d={MARK_MONO} fill="currentColor" />;
  return <>{FACES.map((k) => <path key={k} d={MARK[k]} fill={fill(variant, k)} />)}</>;
}

const a11y = (title?: string) => (title ? { role: 'img', 'aria-label': title } : { 'aria-hidden': true as const, focusable: 'false' as const });

export function LogoMark({ size = 32, title, variant = 'auto', className }: { size?: number; title?: string; variant?: LogoVariant; className?: string }) {
  return (
    <svg className={className} width={size} height={size} viewBox="0 0 64 64" {...a11y(title)}>
      {title && <title>{title}</title>}
      <MarkArt variant={variant} />
    </svg>
  );
}

/**
 * Mark + wordmark. `size` works like a font size (the letters' cap height is about 0.73 × size),
 * so existing callers keep their footprint. `layout` picks the horizontal or stacked lockup.
 */
export function Wordmark({ size = 20, variant = 'auto', layout = 'horizontal', title = 'Agrarian', className }: {
  size?: number; variant?: LogoVariant; layout?: 'horizontal' | 'stacked'; title?: string; className?: string;
}) {
  const cap = size * 0.73;
  const word = (x: number, y: number, c: number) => <path transform={`translate(${x} ${y}) scale(${c / 100})`} d={WORD} fill={fill(variant, 'ink')} />;
  let w: number, h: number, body: JSX.Element;
  if (layout === 'stacked') {
    w = (WORD_WIDTH * LOCKUP.sCap) / 100;
    h = 64 + LOCKUP.sGap + LOCKUP.sCap;
    body = <><g transform={`translate(${(w - 64) / 2} 0)`}><MarkArt variant={variant} /></g>{word(0, 64 + LOCKUP.sGap, LOCKUP.sCap)}</>;
  } else {
    w = 64 + LOCKUP.hGap + (WORD_WIDTH * LOCKUP.hCap) / 100;
    h = 64;
    body = <><MarkArt variant={variant} />{word(64 + LOCKUP.hGap, 32 - LOCKUP.hCap / 2, LOCKUP.hCap)}</>;
  }
  const scale = cap / (layout === 'stacked' ? LOCKUP.sCap : LOCKUP.hCap);
  return (
    <svg className={['wordmark', className].filter(Boolean).join(' ')} width={+(w * scale).toFixed(1)} height={+(h * scale).toFixed(1)} viewBox={`0 0 ${w.toFixed(2)} ${h}`} role="img" aria-label={title}>
      <title>{title}</title>
      {body}
    </svg>
  );
}
